seam=runpy.run_path(str(H/'file_facade_bootstrap.py'))['prepare'](O,C)
cp=':'.join(map(str,[C,O,*a.library]));sources=[H/name for name in ['ActiveFileFacadeOracle.java','CompactOwnerOracle.java','FilePriorityLoadOracle.java']]
with (W/'javac.log').open('w') as log:r=subprocess.run([str(a.java_home/'bin/javac'),'-cp',cp,'-d',str(C),*map(str,sources)],stdout=log,stderr=subprocess.STDOUT)
