argv=[str(a.java_home/'bin/java'),'-Xmx256m','-Dazureus.config.path='+str(W/'config'),'-Dazureus.install.path='+str(W),'-Doracle.expected.classes='+str(O),'-Doracle.expected.manager.classes='+str(C),'-cp',cp,'ActiveFileFacadeOracle',str(W/'fixtures')]
with (W/'stdout').open('w') as out,(W/'stderr').open('w') as err:r=subprocess.run(argv,input=inputs,text=True,stdout=out,stderr=err,timeout=120)
(W/'exit.json').write_text(json.dumps(dict(exit=r.returncode,argv=argv),indent=2)+'\n');assert r.returncode==0,str(W/'stderr')
