with nativeLog.open('w') as stream:r=subprocess.run(argv,stdout=stream,stderr=subprocess.STDOUT,timeout=180)
s=nativeLog.read_text();totals=re.findall(r'Totals: (\d+) passed, (\d+) failed, (\d+) skipped',s);assert r.returncode==0 and totals and all(f=='0' and k=='0' for n,f,k in totals),str(nativeLog)
native=re.findall(r'OBS_CURRENT_FILE_FACADE\t([LCRX])\t([0-4])\t([01])\t([01])\t(-?\d+)',s);assert len(native)==20
values={(kind,int(mode)):(int(stopped),int(active),int(priority)) for kind,mode,stopped,active,priority in native};assert len(values)==20
activeRows=0
for line in observed:
 idx,kind,phase,role,skipped,priority=line.split('\t');kind,mode,sourcePhase=cases[int(idx)];assert sourcePhase==int(phase)
 stopped,active,rank=values[('LCRX'[kind-1],['absent','-1','0','1','-2'].index(mode))];assert int(priority)==rank and int(skipped)==(active if role=='active' else stopped),line
 activeRows+=role=='active'
